use std::collections::HashMap;

use crate::error::{CalcError, Math};

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Op {
    Add,
    Sub,
    Mul,
    Div,
    Pow,
    Mod,
    Fact,
    UPlus,
    UMinus,
    UFact,
}

impl Op {
    /// Precedence: higher binds tighter.
    pub fn prec(self) -> u8 {
        match self {
            Op::Add | Op::Sub => 1,
            Op::Mul | Op::Div | Op::Mod => 2,
            Op::Pow => 3,
            Op::Fact | Op::UFact => 4,
            Op::UPlus | Op::UMinus => 5,
        }
    }

    pub fn right_assoc(self) -> bool {
        matches!(self, Op::Pow | Op::UPlus | Op::UMinus)
    }

    pub fn is_unary(self) -> bool {
        matches!(self, Op::UPlus | Op::UMinus | Op::UFact)
    }

    pub fn symbol(self) -> char {
        match self {
            Op::Add | Op::UPlus => '+',
            Op::Sub | Op::UMinus => '-',
            Op::Mul => '*',
            Op::Div => '/',
            Op::Pow => '^',
            Op::Mod => '%',
            Op::Fact | Op::UFact => '!',
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Num(f64),
    Op(Op),
    Func(&'static str),
    LParen,
    RParen,
    Comma,
}

pub const FUNCTIONS: &[(&str, usize)] = &[
    ("sin", 1),
    ("cos", 1),
    ("tan", 1),
    ("csc", 1),
    ("sec", 1),
    ("cot", 1),
    ("sinh", 1),
    ("cosh", 1),
    ("tanh", 1),
    ("asin", 1),
    ("acos", 1),
    ("atan", 1),
    ("acsc", 1),
    ("asec", 1),
    ("acot", 1),
    ("ln", 1),
    ("log2", 1),
    ("log10", 1),
    ("sqrt", 1),
    ("ceil", 1),
    ("floor", 1),
    ("abs", 1),
    ("round", 1),
    ("deg", 1),
    ("rad", 1),
    ("exp", 1),
    ("exp2", 1),
    ("log", 2),
    ("nroot", 2),
];

pub const CONSTANTS: &[(&str, f64)] = &[("pi", std::f64::consts::PI), ("e", std::f64::consts::E)];

pub const OPERATOR_CHARS: &[char] = &['+', '-', '*', '/', '^', '%', '!'];

pub fn lookup_function(name: &str) -> Option<(&'static str, usize)> {
    FUNCTIONS.iter().find(|(n, _)| *n == name).copied()
}

pub fn function_arity(name: &str) -> usize {
    lookup_function(name).map(|(_, a)| a).unwrap_or(1)
}

pub fn lookup_constant(name: &str) -> Option<f64> {
    CONSTANTS.iter().find(|(n, _)| *n == name).map(|(_, v)| *v)
}

fn is_function_prefix(s: &str) -> bool {
    FUNCTIONS.iter().any(|(n, _)| n.starts_with(s))
}

/// Builds the text shown for the `help` command.  The tables are kept in hash
/// maps, so the listing order is whatever the map iteration yields.
pub fn help_text() -> String {
    let constants: HashMap<&str, f64> = CONSTANTS.iter().copied().collect();
    let functions: HashMap<&str, usize> = FUNCTIONS.iter().copied().collect();
    let operators: HashMap<char, ()> = OPERATOR_CHARS.iter().map(|c| (*c, ())).collect();

    let mut out = String::new();
    out.push_str("Constants\n");
    for name in constants.keys() {
        out.push_str(&format!("{:>8}", name));
    }
    out.push_str("\n\nFunctions\n");
    let names: Vec<&str> = functions.keys().copied().collect();
    for chunk in names.chunks(9) {
        for name in chunk {
            out.push_str(&format!("{:>8}", name));
        }
        out.push('\n');
    }
    out.push_str("\nOperators\n");
    let ops: Vec<String> = operators.keys().map(|c| c.to_string()).collect();
    out.push_str(&ops.join(" "));
    out.push('\n');
    out
}

/// Tokenizes an expression.  `prev_ans` is the value substituted for `_`.
pub fn lex(input: &str, prev_ans: Option<f64>) -> Result<Vec<Token>, CalcError> {
    let input: String = input.trim().chars().filter(|c| *c != ' ').collect();
    if input == "help" {
        return Err(CalcError::Help);
    }

    let mut result: Vec<Token> = Vec::new();
    let mut num_vec = String::new();
    let mut char_vec = String::new();
    let mut last_char_is_op = true;
    let mut depth: usize = 0;

    // Pushes the pending number literal (if it parses) and returns whether a
    // token was produced.
    fn flush_num(num_vec: &mut String, result: &mut Vec<Token>) -> bool {
        if num_vec.is_empty() {
            return false;
        }
        match num_vec.parse::<f64>() {
            Ok(n) => {
                result.push(Token::Num(n));
                num_vec.clear();
                true
            }
            Err(_) => false,
        }
    }

    // Pushes a pending constant (if the identifier is one).
    fn flush_const(char_vec: &mut String, result: &mut Vec<Token>) -> bool {
        if let Some(v) = lookup_constant(char_vec) {
            result.push(Token::Num(v));
            char_vec.clear();
            true
        } else {
            false
        }
    }

    let chars: Vec<char> = input.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        i += 1;
        match c {
            '0'..='9' | '.' => {
                if !char_vec.is_empty() {
                    let mut candidate = char_vec.clone();
                    candidate.push(c);
                    if is_function_prefix(&candidate) {
                        char_vec.push(c);
                        last_char_is_op = false;
                        continue;
                    } else if lookup_function(&char_vec).is_some() {
                        return Err(CalcError::Syntax(format!(
                            "Function '{}' expected parentheses",
                            char_vec
                        )));
                    } else if flush_const(&mut char_vec, &mut result) {
                        result.push(Token::Op(Op::Mul));
                    } else {
                        return Err(CalcError::Syntax(format!(
                            "Unexpected character '{}'",
                            candidate
                        )));
                    }
                }
                num_vec.push(c);
                last_char_is_op = false;
            }
            'a'..='z' | 'A'..='Z' => {
                if flush_num(&mut num_vec, &mut result) {
                    result.push(Token::Op(Op::Mul));
                }
                char_vec.push(c);
                last_char_is_op = false;
            }
            '_' => {
                if !char_vec.is_empty() {
                    return Err(CalcError::Syntax(format!(
                        "Unexpected character '{}'",
                        char_vec
                    )));
                }
                if flush_num(&mut num_vec, &mut result) {
                    result.push(Token::Op(Op::Mul));
                }
                match prev_ans {
                    Some(v) => result.push(Token::Num(v)),
                    None => return Err(CalcError::Syntax("No previous answer!".to_string())),
                }
                last_char_is_op = false;
            }
            '(' => {
                if !char_vec.is_empty() {
                    match lookup_function(&char_vec) {
                        Some((name, _)) => {
                            result.push(Token::Func(name));
                            char_vec.clear();
                        }
                        None => {
                            return Err(CalcError::Syntax(format!(
                                "Unknown function '{}'",
                                char_vec
                            )))
                        }
                    }
                } else if flush_num(&mut num_vec, &mut result) {
                    result.push(Token::Op(Op::Mul));
                } else if matches!(result.last(), Some(Token::RParen)) {
                    result.push(Token::Op(Op::Mul));
                }
                result.push(Token::LParen);
                depth += 1;
                last_char_is_op = true;
            }
            ')' => {
                if depth == 0 {
                    return Err(CalcError::Syntax("Mismatched parentheses!".to_string()));
                }
                depth -= 1;
                flush_num(&mut num_vec, &mut result);
                flush_const(&mut char_vec, &mut result);
                result.push(Token::RParen);
                last_char_is_op = false;
            }
            '+' | '-' => {
                let flushed =
                    flush_num(&mut num_vec, &mut result) | flush_const(&mut char_vec, &mut result);
                let binary = if c == '+' { Op::Add } else { Op::Sub };
                let unary = if c == '+' { Op::UPlus } else { Op::UMinus };
                if flushed {
                    result.push(Token::Op(binary));
                    last_char_is_op = true;
                } else if last_char_is_op {
                    result.push(Token::Op(unary));
                } else {
                    result.push(Token::Op(binary));
                }
            }
            '*' | '/' | '^' | '%' => {
                flush_num(&mut num_vec, &mut result);
                flush_const(&mut char_vec, &mut result);
                let op = match c {
                    '*' => {
                        if i < chars.len() && chars[i] == '*' {
                            i += 1;
                            Op::Pow
                        } else {
                            Op::Mul
                        }
                    }
                    '/' => Op::Div,
                    '^' => Op::Pow,
                    _ => Op::Mod,
                };
                result.push(Token::Op(op));
                last_char_is_op = true;
            }
            '!' => {
                flush_num(&mut num_vec, &mut result);
                flush_const(&mut char_vec, &mut result);
                if last_char_is_op {
                    result.push(Token::Op(Op::UFact));
                } else {
                    result.push(Token::Op(Op::Fact));
                }
                last_char_is_op = false;
            }
            ',' => {
                flush_num(&mut num_vec, &mut result);
                flush_const(&mut char_vec, &mut result);
                result.push(Token::Comma);
            }
            _ => {
                return Err(CalcError::Syntax(format!("Unexpected token: '{}'", c)));
            }
        }
    }
    flush_num(&mut num_vec, &mut result);
    flush_const(&mut char_vec, &mut result);
    Ok(result)
}

#[allow(dead_code)]
pub fn math_err(m: Math) -> CalcError {
    CalcError::Math(m)
}
EOF
echo done"}

