const DIGITS: &[u8] = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

/// Inserts a thousands separator every three characters, counting from the
/// right of the string.
fn group(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut out = String::with_capacity(n + n / 3);
    for (i, c) in chars.iter().enumerate() {
        if i > 0 && (n - i) % 3 == 0 {
            out.push(',');
        }
        out.push(*c);
    }
    out
}

/// Converts a non-negative decimal integer string to the given radix exactly.
fn convert_integer(decimal: &str, base: u32) -> String {
    let mut digits: Vec<u32> = decimal
        .bytes()
        .filter(|b| b.is_ascii_digit())
        .map(|b| (b - b'0') as u32)
        .collect();
    // strip leading zeros
    while digits.len() > 1 && digits[0] == 0 {
        digits.remove(0);
    }
    if digits.is_empty() || (digits.len() == 1 && digits[0] == 0) {
        return "0".to_string();
    }
    let mut out: Vec<u8> = Vec::new();
    while !(digits.len() == 1 && digits[0] == 0) {
        // long division by base
        let mut rem: u32 = 0;
        let mut next: Vec<u32> = Vec::with_capacity(digits.len());
        for d in &digits {
            let cur = rem * 10 + *d;
            let q = cur / base;
            rem = cur % base;
            if !(next.is_empty() && q == 0) {
                next.push(q);
            }
        }
        out.push(DIGITS[rem as usize]);
        if next.is_empty() {
            next.push(0);
        }
        digits = next;
    }
    out.reverse();
    String::from_utf8(out).unwrap()
}

fn convert_fraction(frac: &str, base: u32, fix: usize) -> String {
    let mut f: f64 = format!("0.{}", frac).parse().unwrap_or(0.0);
    let mut out = String::new();
    for _ in 0..fix {
        f *= base as f64;
        let d = f.floor();
        out.push(DIGITS[(d as usize).min(35)] as char);
        f -= d;
        if f == 0.0 {
            break;
        }
    }
    if out.is_empty() {
        out.push('0');
    }
    out
}

/// Formats the result the way it is printed to the user.
pub fn pprint(value: f64, fix: usize, base: u32) -> String {
    let s = format!("{:.*}", fix, value);
    if base == 10 {
        let (int_part, frac_part) = match s.find('.') {
            Some(idx) => (&s[..idx], Some(&s[idx + 1..])),
            None => (&s[..], None),
        };
        let (sign, digits) = if let Some(rest) = int_part.strip_prefix('-') {
            ("-", rest)
        } else {
            ("", int_part)
        };
        let mut out = String::from(sign);
        out.push_str(&group(digits));
        if let Some(frac) = frac_part {
            out.push('.');
            out.push_str(frac);
        }
        out
    } else {
        let (int_part, frac_part) = match s.find('.') {
            Some(idx) => (&s[..idx], &s[idx + 1..]),
            None => return group(&s),
        };
        let (sign, digits) = if let Some(rest) = int_part.strip_prefix('-') {
            ("-", rest)
        } else {
            ("", int_part)
        };
        let int_conv = format!("{}{}", sign, convert_integer(digits, base));
        let padded = format!("{:>10}", int_conv);
        let frac_conv = convert_fraction(frac_part, base, fix);
        format!("{}.{}", group(&padded), frac_conv)
    }
}

/// Rounds a value to the configured number of decimals by formatting and
/// parsing it back, mirroring how the previous answer is stored.
pub fn round_to_fix(value: f64, fix: usize) -> f64 {
    format!("{:.*}", fix, value).parse().unwrap_or(value)
}
