            None => return group(&s),
        };
        let (sign, digits) = if let Some(rest) = int_part.strip_prefix('-') {
            ("-", rest)
        } else {
            ("", int_part)
        };
        let int_conv = format!("{}{}", sign, convert_integer(digits, base));
        let padded = format!("{:>10}", int_conv);
        let frac_conv = convert_fraction(frac_part, base, fix);
        format!("{}.{}", group(&padded), frac_conv)
    }
}

/// Rounds a value to the configured number of decimals by formatting and
/// parsing it back, mirroring how the previous answer is stored.
pub fn round_to_fix(value: f64, fix: usize) -> f64 {
    format!("{:.*}", fix, value).parse().unwrap_or(value)
