fn convert_integer(decimal: &str, base: u32) -> String {
    let mut digits: Vec<u32> = decimal.bytes().filter(|b| b.is_ascii_digit()).map(|b| (b - b'0') as u32).collect();
    while digits.len() > 1 && digits[0] == 0 { digits.remove(0); }
    if digits.is_empty() || (digits.len() == 1 && digits[0] == 0) { return "0".to_string(); }
