//! Persistent command history with the same file format and semantics as
//! the classic line editor history files ("#V2" escaped format).

use std::collections::VecDeque;
use std::fs::{File, OpenOptions};
use std::io::{self, BufRead, BufReader, Read, Seek, SeekFrom, Write};
use std::os::unix::fs::OpenOptionsExt;
use std::path::Path;

const HEADER: &str = "#V2";

#[derive(Debug, Clone)]
pub struct History {
    entries: VecDeque<String>,
    max_len: usize,
    ignore_space: bool,
    ignore_dups: bool,
    new_entries: usize,
}

impl History {
    pub fn new(max_len: usize) -> Self {
        History {
            entries: VecDeque::new(),
            max_len,
            ignore_space: true,
            ignore_dups: true,
            new_entries: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    pub fn get(&self, idx: usize) -> Option<&String> {
        self.entries.get(idx)
    }

    /// Adds a line, applying the ignore rules.  Returns whether it was added.
    pub fn add(&mut self, line: &str) -> bool {
        if self.max_len == 0 {
            return false;
        }
        if line.is_empty()
            || (self.ignore_space && line.chars().next().map_or(true, char::is_whitespace))
        {
            return false;
        }
        if self.ignore_dups {
            if let Some(last) = self.entries.back() {
                if last == line {
                    return false;
                }
            }
        }
        if self.entries.len() == self.max_len {
            self.entries.pop_front();
        }
        self.entries.push_back(line.to_string());
        self.new_entries = (self.new_entries + 1).min(self.max_len);
        true
    }

    /// Searches backwards from `start` (inclusive) for an entry starting
    /// with `prefix`.
    pub fn starts_with_rev(&self, prefix: &str, start: usize) -> Option<(usize, &String)> {
        if self.entries.is_empty() {
            return None;
        }
        let mut idx = start.min(self.entries.len() - 1);
        loop {
            let entry = &self.entries[idx];
            if entry.starts_with(prefix) {
                return Some((idx, entry));
            }
            if idx == 0 {
                return None;
            }
            idx -= 1;
        }
    }

    /// Searches forwards from `start` (inclusive) for an entry starting
    /// with `prefix`.
    pub fn starts_with_fwd(&self, prefix: &str, start: usize) -> Option<(usize, &String)> {
        (start..self.entries.len()).find_map(|idx| {
            let entry = &self.entries[idx];
            if entry.starts_with(prefix) {
                Some((idx, entry))
            } else {
                None
            }
        })
    }

    fn load_from<R: Read>(&mut self, reader: R) -> io::Result<()> {
        let reader = BufReader::new(reader);
        let mut lines = reader.lines();
        let mut v2 = false;
        if let Some(first) = lines.next() {
            let first = first?;
            if first == HEADER {
                v2 = true;
            } else {
                self.add(&first);
            }
        }
        for line in lines {
            let line = line?;
            if v2 {
                self.add(&unescape(&line));
            } else {
                self.add(&line);
            }
        }
        self.new_entries = 0;
        Ok(())
    }

    /// Loads the history file; fails if it cannot be read.
    pub fn load(&mut self, path: &Path) -> io::Result<()> {
        let file = File::open(path)?;
        self.load_from(file)
    }

    fn write_all<W: Write>(&self, mut w: W) -> io::Result<()> {
        let mut out = String::new();
        out.push_str(HEADER);
        out.push('\n');
        for entry in &self.entries {
            out.push_str(&escape(entry));
            out.push('\n');
        }
        w.write_all(out.as_bytes())?;
        w.flush()
    }

    /// Persists the history, merging with whatever the file contains.
    pub fn save(&mut self, path: &Path) -> io::Result<()> {
        if self.entries.is_empty() || self.max_len == 0 || self.new_entries == 0 {
            return Ok(());
        }
        if !path.exists() {
            let file = OpenOptions::new()
                .write(true)
                .create(true)
                .truncate(true)
                .mode(0o600)
                .open(path)?;
            self.write_all(file)?;
            self.new_entries = 0;
            return Ok(());
        }
        let mut file = OpenOptions::new().read(true).write(true).open(path)?;
        let mut other = History::new(self.max_len);
        other.ignore_space = self.ignore_space;
        other.ignore_dups = self.ignore_dups;
        other.load_from(&mut file)?;
        let first_new = self.entries.len().saturating_sub(self.new_entries);
        for idx in first_new..self.entries.len() {
            let entry = self.entries[idx].clone();
            other.add(&entry);
        }
        file.seek(SeekFrom::Start(0))?;
        file.set_len(0)?;
        other.write_all(&mut file)?;
        self.new_entries = 0;
        Ok(())
    }
}

fn escape(entry: &str) -> String {
    let mut out = String::with_capacity(entry.len());
    for c in entry.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            c => out.push(c),
        }
    }
    out
}

fn unescape(line: &str) -> String {
    let mut out = String::with_capacity(line.len());
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.peek() {
                Some('n') => {
                    chars.next();
                    out.push('\n');
                }
                Some('\\') => {
                    chars.next();
                    out.push('\\');
                }
                _ => out.push('\\'),
            }
        } else {
            out.push(c);
        }
    }
    out
}
