//! Low level terminal access: raw mode, key decoding and window size.

use std::io::{self, Read, Write};
use std::mem::MaybeUninit;
use std::os::unix::io::AsRawFd;

pub const BRACKETED_PASTE_ON: &str = "\x1b[?2004h";
pub const BRACKETED_PASTE_OFF: &str = "\x1b[?2004l";
pub const BEGIN_SYNC: &str = "\x1b[?2026h";
pub const END_SYNC: &str = "\x1b[?2026l";

pub fn is_tty(fd: i32) -> bool {
    unsafe { libc::isatty(fd) == 1 }
}

pub fn is_unsupported_term() -> bool {
    match std::env::var("TERM") {
        Ok(term) => term == "dumb",
        Err(_) => false,
    }
}

/// Terminal width of stdout, 80 if it cannot be determined.
pub fn columns() -> usize {
    unsafe {
        let mut ws: MaybeUninit<libc::winsize> = MaybeUninit::zeroed();
        if libc::ioctl(libc::STDOUT_FILENO, libc::TIOCGWINSZ, ws.as_mut_ptr()) == 0 {
            let ws = ws.assume_init();
            if ws.ws_col > 0 {
                return ws.ws_col as usize;
            }
        }
    }
    80
}

pub struct RawMode {
    original: libc::termios,
}

impl RawMode {
    pub fn enable() -> io::Result<RawMode> {
        unsafe {
            let mut original: MaybeUninit<libc::termios> = MaybeUninit::zeroed();
            if libc::tcgetattr(libc::STDIN_FILENO, original.as_mut_ptr()) != 0 {
                return Err(io::Error::last_os_error());
            }
            let original = original.assume_init();
            let mut raw = original;
            raw.c_iflag &= !(libc::BRKINT | libc::ICRNL | libc::INPCK | libc::ISTRIP | libc::IXON);
            raw.c_cflag |= libc::CS8;
            raw.c_lflag &= !(libc::ECHO | libc::ICANON | libc::IEXTEN | libc::ISIG);
            raw.c_cc[libc::VMIN] = 1;
            raw.c_cc[libc::VTIME] = 0;
            if libc::tcsetattr(libc::STDIN_FILENO, libc::TCSADRAIN, &raw) != 0 {
                return Err(io::Error::last_os_error());
            }
            let mut out = io::stdout();
            let _ = out.write_all(BRACKETED_PASTE_ON.as_bytes());
            let _ = out.flush();
            Ok(RawMode { original })
        }
    }

    pub fn disable(&self) {
        let mut out = io::stdout();
        let _ = out.write_all(BRACKETED_PASTE_OFF.as_bytes());
        let _ = out.flush();
        unsafe {
            libc::tcsetattr(libc::STDIN_FILENO, libc::TCSADRAIN, &self.original);
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Key {
    Char(char),
    Ctrl(char),
    Meta(char),
    Enter,
    Tab,
    BackTab,
    Backspace,
    Delete,
    Insert,
    Up,
    Down,
    Left,
    Right,
    Home,
    End,
    PageUp,
    PageDown,
    CtrlLeft,
    CtrlRight,
    MetaBackspace,
    Esc,
    Paste(String),
    Unknown,
}

pub struct KeyReader {
    pending: Vec<u8>,
}

impl KeyReader {
    pub fn new() -> Self {
        KeyReader {
            pending: Vec::new(),
        }
    }

    fn read_byte(&mut self) -> io::Result<Option<u8>> {
        if !self.pending.is_empty() {
            return Ok(Some(self.pending.remove(0)));
        }
        let mut buf = [0u8; 1];
        loop {
            match io::stdin().lock().read(&mut buf) {
                Ok(0) => return Ok(None),
                Ok(_) => return Ok(Some(buf[0])),
                Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(e) => return Err(e),
            }
        }
    }

    /// Reads a byte, giving up after `timeout_ms` when nothing arrives.
    fn read_byte_timeout(&mut self, timeout_ms: i32) -> io::Result<Option<u8>> {
        if !self.pending.is_empty() {
            return Ok(Some(self.pending.remove(0)));
        }
        let mut fds = libc::pollfd {
            fd: io::stdin().as_raw_fd(),
            events: libc::POLLIN,
            revents: 0,
        };
        let r = unsafe { libc::poll(&mut fds, 1, timeout_ms) };
        if r <= 0 {
            return Ok(None);
        }
        self.read_byte()
    }

    fn read_char_from(&mut self, first: u8) -> io::Result<Option<char>> {
        let width = if first < 0x80 {
            1
        } else if first >> 5 == 0b110 {
            2
        } else if first >> 4 == 0b1110 {
            3
        } else if first >> 3 == 0b11110 {
            4
        } else {
            1
        };
        let mut bytes = vec![first];
        while bytes.len() < width {
            match self.read_byte()? {
                Some(b) => bytes.push(b),
                None => return Ok(None),
            }
        }
        Ok(Some(
            String::from_utf8_lossy(&bytes).chars().next().unwrap_or('\u{fffd}'),
        ))
    }

    /// Reads the next key; `None` on end of input.
    pub fn read_key(&mut self) -> io::Result<Option<Key>> {
        let b = match self.read_byte()? {
            Some(b) => b,
            None => return Ok(None),
        };
        match b {
            0x1b => self.read_escape(),
            b'\r' | b'\n' => Ok(Some(Key::Enter)),
            b'\t' => Ok(Some(Key::Tab)),
            0x7f | 0x08 => Ok(Some(Key::Backspace)),
            0..=0x1f => Ok(Some(Key::Ctrl(((b + 0x40) as char).to_ascii_uppercase()))),
            _ => Ok(self.read_char_from(b)?.map(Key::Char)),
        }
    }

    fn read_escape(&mut self) -> io::Result<Option<Key>> {
        let b = match self.read_byte_timeout(100)? {
            Some(b) => b,
            None => return Ok(Some(Key::Esc)),
        };
        match b {
            b'[' => {
                let mut params = String::new();
                loop {
                    let c = match self.read_byte()? {
                        Some(c) => c,
                        None => return Ok(None),
                    };
                    if (0x40..=0x7e).contains(&c) {
                        return Ok(Some(self.csi(&params, c)?));
                    }
                    params.push(c as char);
                    if params.len() > 32 {
                        return Ok(Some(Key::Unknown));
                    }
                }
            }
            b'O' => {
                let c = match self.read_byte()? {
                    Some(c) => c,
                    None => return Ok(None),
                };
                Ok(Some(match c {
                    b'A' => Key::Up,
                    b'B' => Key::Down,
                    b'C' => Key::Right,
                    b'D' => Key::Left,
                    b'H' => Key::Home,
                    b'F' => Key::End,
