{"command":"cat > /workspace/src/readline/mod.rs <<'EOF'
//! A small line editor with emacs key bindings, history, hints and syntax
//! highlighting, modelled after the behaviour of the usual readline-like
//! crates (prompt rendering, bracketed paste, synchronized updates, ...).

pub mod history;
pub mod term;

use std::io::{self, BufRead, Write};

use history::History;
use term::{Key, KeyReader, RawMode};

/// Behaviour hooks for highlighting.
pub trait Helper {
    /// Highlights the whole input line (ANSI escape sequences allowed).
    fn highlight(&self, line: &str) -> String;
    /// Highlights a hint displayed after the cursor.
    fn highlight_hint(&self, hint: &str) -> String;
}

#[derive(Debug)]
pub enum ReadlineError {
    Io(io::Error),
    Eof,
    Interrupted,
}

impl From<io::Error> for ReadlineError {
    fn from(e: io::Error) -> Self {
        ReadlineError::Io(e)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
struct Position {
    col: usize,
    row: usize,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
struct Layout {
    cursor: Position,
    end: Position,
}

pub struct Editor<H: Helper> {
    history: History,
    helper: Option<H>,
    kill_ring: Vec<String>,
    kill_index: usize,
}

const MAX_UNDO: usize = 200;

fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp < 0x20 || cp == 0x7f {
        return 0;
    }
    // combining marks
    if (0x0300..=0x036f).contains(&cp)
        || (0x1ab0..=0x1aff).contains(&cp)
        || (0x1dc0..=0x1dff).contains(&cp)
        || (0x20d0..=0x20ff).contains(&cp)
        || (0xfe20..=0xfe2f).contains(&cp)
        || cp == 0x200b
    {
        return 0;
    }
    // wide / fullwidth
    if (0x1100..=0x115f).contains(&cp)
        || (0x2e80..=0x303e).contains(&cp)
        || (0x3041..=0x33ff).contains(&cp)
        || (0x3400..=0x4dbf).contains(&cp)
        || (0x4e00..=0x9fff).contains(&cp)
        || (0xa000..=0xa4cf).contains(&cp)
        || (0xac00..=0xd7a3).contains(&cp)
        || (0xf900..=0xfaff).contains(&cp)
        || (0xfe30..=0xfe4f).contains(&cp)
        || (0xff00..=0xff60).contains(&cp)
        || (0xffe0..=0xffe6).contains(&cp)
        || (0x1f300..=0x1f64f).contains(&cp)
        || (0x1f900..=0x1f9ff).contains(&cp)
        || (0x20000..=0x3fffd).contains(&cp)
    {
        return 2;
    }
    1
}

fn is_word_char(c: char) -> bool {
    c.is_alphanumeric()
}

struct State<'a, H: Helper> {
    prompt: &'a str,
    prompt_size: Position,
    cols: usize,
    line: Vec<char>,
    pos: usize,
    layout: Layout,
    hint: Option<String>,
    history_index: usize,
    saved_line: Option<(Vec<char>, usize)>,
    undo: Vec<(Vec<char>, usize)>,
    colors: bool,
    helper: Option<&'a H>,
    history: &'a History,
    out: io::Stdout,
    last_action_kill: bool,
    last_action_yank: Option<(usize, usize)>,
}

impl<'a, H: Helper> State<'a, H> {
    fn calculate_position(&self, s: &[char], orig: Position) -> Position {
        let mut pos = orig;
        for &c in s {
            if c == '\n' {
                pos.row += 1;
                pos.col = 0;
                continue;
            }
            let cw = char_width(c);
            pos.col += cw;
            if pos.col > self.cols {
                pos.row += 1;
                pos.col = cw;
            }
        }
        if pos.col == self.cols {
            pos.col = 0;
            pos.row += 1;
        }
        pos
    }

    fn line_string(&self) -> String {
        self.line.iter().collect()
    }

    fn write(&mut self, s: &str) -> io::Result<()> {
        self.out.write_all(s.as_bytes())?;
        self.out.flush()
    }

    fn beep(&mut self) -> io::Result<()> {
        self.write("\x07")
    }

    /// Recomputes the history based hint for the current line.
    fn update_hint(&mut self) {
        self.hint = None;
        if self.line.is_empty() || self.pos < self.line.len() {
            return;
        }
        let start = if self.history_index == self.history.len() {
            self.history_index.saturating_sub(1)
        } else {
            self.history_index
        };
        let line = self.line_string();
        if let Some((_, entry)) = self.history.starts_with_rev(&line, start) {
            if *entry != line {
                self.hint = Some(entry[line.len()..].to_string());
            }
        }
    }

    fn refresh(&mut self, with_hint: bool) -> io::Result<()> {
        let hint = if with_hint { self.hint.clone() } else { None };
        let cursor = self.calculate_position(&self.line[..self.pos], self.prompt_size);
        let mut end = if self.pos == self.line.len() {
            cursor
        } else {
            self.calculate_position(&self.line[self.pos..], cursor)
        };
        if let Some(h) = &hint {
            let hc: Vec<char> = h.chars().collect();
            end = self.calculate_position(&hc, end);
        }

        let mut buf = String::new();
        buf.push_str(term::BEGIN_SYNC);
        let old = self.layout;
        let cursor_row_movement = old.end.row.saturating_sub(old.cursor.row);
        if cursor_row_movement > 0 {
            buf.push_str(&format!("\x1b[{}B", cursor_row_movement));
        }
        for _ in 0..old.end.row {
            buf.push_str("\r\x1b[K\x1b[A");
        }
        buf.push_str("\r\x1b[K");
        let line = self.line_string();
        buf.push_str(self.prompt);
        match (self.colors, self.helper) {
            (true, Some(h)) => buf.push_str(&h.highlight(&line)),
            _ => buf.push_str(&line),
        }
        if let Some(hint_text) = &hint {
            match (self.colors, self.helper) {
                (true, Some(h)) => buf.push_str(&h.highlight_hint(hint_text)),
                _ => buf.push_str(hint_text),
            }
        }
        if end.col == 0 && end.row > 0 && !hint.as_deref().map_or(false, |h| h.ends_with('\n')) {
            buf.push('\n');
        }
        let up = end.row.saturating_sub(cursor.row);
        if up > 0 {
            buf.push_str(&format!("\x1b[{}A", up));
        }
        if cursor.col > 0 {
            buf.push_str(&format!("\r\x1b[{}C", cursor.col));
        } else {
            buf.push('\r');
        }
        buf.push_str(term::END_SYNC);
        self.layout = Layout { cursor, end };
        self.write(&buf)
    }

    /// Called after the cursor moved without the text changing.
    fn move_cursor(&mut self) -> io::Result<()> {
        let cursor = self.calculate_position(&self.line[..self.pos], self.prompt_size);
        if self.layout.cursor == cursor {
            return Ok(());
        }
        if self.colors {
            self.update_hint();
            return self.refresh(true);
        }
        let old = self.layout.cursor;
        let mut buf = String::new();
        if cursor.row > old.row {
            let shift = cursor.row - old.row;
            if shift == 1 {
                buf.push_str("\x1b[B");
            } else {
                buf.push_str(&format!("\x1b[{}B", shift));
            }
        } else if cursor.row < old.row {
            let shift = old.row - cursor.row;
            if shift == 1 {
                buf.push_str("\x1b[A");
            } else {
                buf.push_str(&format!("\x1b[{}A", shift));
            }
        }
        if cursor.col > old.col {
            let shift = cursor.col - old.col;
            if shift == 1 {
                buf.push_str("\x1b[C");
            } else {
                buf.push_str(&format!("\x1b[{}C", shift));
            }
        } else if cursor.col < old.col {
            let shift = old.col - cursor.col;
            if shift == 1 {
                buf.push_str("\x1b[D");
            } else {
                buf.push_str(&format!("\x1b[{}D", shift));
            }
        }
        self.layout.cursor = cursor;
        self.write(&buf)
    }

    /// Called after the text changed.
    fn changed(&mut self) -> io::Result<()> {
        self.update_hint();
        self.refresh(true)
    }

    fn snapshot(&mut self) {
        if self.undo.len() >= MAX_UNDO {
            self.undo.remove(0);
        }
        self.undo.push((self.line.clone(), self.pos));
    }

    fn insert_char(&mut self, c: char) -> io::Result<()> {
        self.snapshot();
        self.line.insert(self.pos, c);
        self.pos += 1;
        let had_hint = self.hint.is_some();
        self.update_hint();
        if !self.colors && self.pos == self.line.len() && !had_hint && self.hint.is_none() && char_width(c) > 0 {
            // trivial case: append the character at the end of the line
            let w = char_width(c);
            let mut cursor = self.layout.cursor;
            cursor.col += w;
            if cursor.col >= self.cols {
                // wrapped: fall back to a full refresh
                return self.refresh(true);
            }
            self.layout.cursor = cursor;
            self.layout.end = cursor;
            let mut tmp = [0u8; 4];
            let s = c.encode_utf8(&mut tmp);
            return self.write(s);
        }
        self.refresh(true)
    }

    fn insert_str(&mut self, text: &str) -> io::Result<()> {
        if text.is_empty() {
            return Ok(());
        }
        self.snapshot();
        for c in text.chars() {
            self.line.insert(self.pos, c);
            self.pos += 1;
        }
        self.changed()
    }

    fn kill(&mut self, start: usize, end: usize, ring: &mut Vec<String>, append: bool) -> io::Result<()> {
        if start >= end {
            return Ok(());
        }
        self.snapshot();
        let text: String = self.line[start..end].iter().collect();
        self.line.drain(start..end);
        self.pos = start;
        if self.last_action_kill && !ring.is_empty() {
            let last = ring.len() - 1;
            if append {
                ring[last].push_str(&text);
            } else {
                ring[last] = format!("{}{}", text, ring[last]);
            }
        } else {
            ring.push(text);
        }
        self.changed()
    }

    fn prev_word_start(&self, big: bool) -> usize {
        let mut i = self.pos;
        if big {
            while i > 0 && self.line[i - 1].is_whitespace() {
                i -= 1;
            }
            while i > 0 && !self.line[i - 1].is_whitespace() {
                i -= 1;
            }
        } else {
            while i > 0 && !is_word_char(self.line[i - 1]) {
                i -= 1;
            }
            while i > 0 && is_word_char(self.line[i - 1]) {
                i -= 1;
            }
        }
        i
    }

    fn next_word_end(&self) -> usize {
        let n = self.line.len();
        let mut i = self.pos;
        while i < n && !is_word_char(self.line[i]) {
            i += 1;
        }
        while i < n && is_word_char(self.line[i]) {
            i += 1;
        }
        i
    }

    fn history_move(&mut self, prev: bool) -> io::Result<()> {
        if self.history.is_empty() {
            return Ok(());
        }
        if self.history_index == self.history.len() {
            if prev {
                self.saved_line = Some((self.line.clone(), self.pos));
            } else {
                return Ok(());
            }
        } else if self.history_index == 0 && prev {
            return Ok(());
        }
        if prev {
            self.history_index -= 1;
        } else {
            self.history_index += 1;
        }
        self.snapshot();
        if self.history_index < self.history.len() {
            let entry = self.history.get(self.history_index).unwrap();
            self.line = entry.chars().collect();
            self.pos = self.line.len();
        } else if let Some((l, p)) = self.saved_line.take() {
            self.line = l;
            self.pos = p;
        }
        self.changed()
    }

    fn history_edge(&mut self, first: bool) -> io::Result<()> {
        if self.history.is_empty() {
            return Ok(());
        }
        if first {
            if self.history_index == self.history.len() {
                self.saved_line = Some((self.line.clone(), self.pos));
            } else if self.history_index == 0 {
                return Ok(());
            }
            self.history_index = 0;
            self.snapshot();
            let entry = self.history.get(0).unwrap();
            self.line = entry.chars().collect();
            self.pos = self.line.len();
        } else {
            if self.history_index == self.history.len() {
                return Ok(());
            }
            self.history_index = self.history.len();
            self.snapshot();
            if let Some((l, p)) = self.saved_line.take() {
                self.line = l;
                self.pos = p;
            } else {
                self.line.clear();
                self.pos = 0;
            }
        }
        self.changed()
    }

    fn history_search(&mut self, prev: bool) -> io::Result<()> {
        if self.history.is_empty() {
            return Ok(());
        }
        let prefix: String = self.line[..self.pos].iter().collect();
        let found = if prev {
            if self.history_index == 0 {
                None
            } else {
                let start = self.history_index.min(self.history.len()) - 1;
                self.history.starts_with_rev(&prefix, start).map(|(i, e)| (i, e.clone()))
            }
        } else {
            if self.history_index + 1 >= self.history.len() {
                None
            } else {
                self.history.starts_with_fwd(&prefix, self.history_index + 1).map(|(i, e)| (i, e.clone()))
            }
        };
        match found {
            Some((idx, entry)) => {
                if self.history_index == self.history.len() {
                    self.saved_line = Some((self.line.clone(), self.pos));
                }
                self.history_index = idx;
                self.snapshot();
                self.line = entry.chars().collect();
                self.pos = self.pos.min(self.line.len());
                self.changed()
            }
            None => self.beep(),
        }
    }
}

impl<H: Helper> Editor<H> {
    pub fn new(history: History) -> Self {
        Editor {
            history,
            helper: None,
            kill_ring: Vec::new(),
            kill_index: 0,
        }
    }

    pub fn set_helper(&mut self, helper: H) {
        self.helper = Some(helper);
    }

    pub fn history_mut(&mut self) -> &mut History {
        &mut self.history
    }

    pub fn add_history_entry(&mut self, line: &str) -> bool {
        self.history.add(line)
    }

    fn read_direct() -> Result<String, ReadlineError> {
        let mut input = String::new();
        let n = io::stdin().lock().read_line(&mut input)?;
        if n == 0 {
            return Err(ReadlineError::Eof);
        }
        if input.ends_with('\n') {
            input.pop();
            if input.ends_with('\r') {
                input.pop();
            }
        }
        Ok(input)
    }

    pub fn readline(&mut self, prompt: &str) -> Result<String, ReadlineError> {
        if term::is_unsupported_term() {
            let mut out = io::stdout();
            out.write_all(prompt.as_bytes())?;
            out.flush()?;
            return Self::read_direct();
        }
        if !term::is_tty(libc::STDIN_FILENO) {
            return Self::read_direct();
        }
        let raw = RawMode::enable()?;
        let result = self.edit(prompt);
        raw.disable();
        let mut out = io::stdout();
        let _ = out.write_all(b"\n");
        let _ = out.flush();
        result
    }

    fn edit(&mut self, prompt: &str) -> Result<String, ReadlineError> {
        let colors = term::is_tty(libc::STDOUT_FILENO);
        let cols = term::columns();
        let prompt_chars: Vec<char> = prompt.chars().collect();
        let mut st = State {
            prompt,
            prompt_size: Position::default(),
            cols,
            line: Vec::new(),
            pos: 0,
            layout: Layout::default(),
            hint: None,
            history_index: self.history.len(),
            saved_line: None,
            undo: Vec::new(),
            colors,
            helper: self.helper.as_ref(),
            history: &self.history,
            out: io::stdout(),
            last_action_kill: false,
            last_action_yank: None,
        };
        st.prompt_size = st.calculate_position(&prompt_chars, Position::default());
        st.refresh(true)?;

        let mut reader = KeyReader::new();
        let mut ring = std::mem::take(&mut self.kill_ring);
        let mut ctrl_x = false;
        loop {
            let key = match reader.read_key()? {
                Some(k) => k,
                None => {
                    self.kill_ring = ring;
                    return Err(ReadlineError::Eof);
                }
            };
            let mut this_kill = false;
            let mut this_yank: Option<(usize, usize)> = None;
            if ctrl_x {
                ctrl_x = false;
                match key {
                    Key::Ctrl('U') => {
                        if let Some((l, p)) = st.undo.pop() {
                            st.line = l;
                            st.pos = p;
                            st.changed()?;
                        }
                    }
                    _ => {}
                }
                continue;
            }
            match key {
                Key::Char(c) => st.insert_char(c)?,
                Key::Paste(text) => {
                    let text = text.replace("\r\n", "\n").replace('\r', "\n");
                    st.insert_str(&text)?;
                }
                Key::Enter | Key::Ctrl('J') | Key::Ctrl('M') => {
                    if st.pos != st.line.len() {
                        st.pos = st.line.len();
                        st.move_cursor()?;
                    }
                    if st.hint.is_some() || st.colors {
                        st.refresh(false)?;
                    }
                    self.kill_ring = ring;
                    return Ok(st.line_string());
                }
                Key::Ctrl('C') => {
                    self.kill_ring = ring;
                    return Err(ReadlineError::Interrupted);
                }
                Key::Ctrl('D') => {
                    if st.line.is_empty() {
                        if st.hint.is_some() || st.colors {
                            st.refresh(false)?;
                        }
                        self.kill_ring = ring;
                        return Err(ReadlineError::Eof);
                    } else if st.pos < st.line.len() {
                        st.snapshot();
                        st.line.remove(st.pos);
                        st.changed()?;
                    }
                }
                Key::Delete => {
                    if st.pos < st.line.len() {
                        st.snapshot();
                        st.line.remove(st.pos);
                        st.changed()?;
                    }
                }
                Key::Backspace | Key::Ctrl('H') => {
                    if st.pos > 0 {
                        st.snapshot();
                        st.pos -= 1;
                        st.line.remove(st.pos);
                        st.changed()?;
                    }
                }
                Key::Left | Key::Ctrl('B') => {
                    if st.pos > 0 {
                        st.pos -= 1;
                        st.move_cursor()?;
                    }
                }
                Key::Right | Key::Ctrl('F') => {
                    if st.pos < st.line.len() {
                        st.pos += 1;
                        st.move_cursor()?;
                    } else if let Some(h) = st.hint.clone() {
                        st.insert_str(&h)?;
                    }
                }
                Key::Home | Key::Ctrl('A') => {
                    if st.pos > 0 {
                        st.pos = 0;
                        st.move_cursor()?;
                    }
                }
                Key::End | Key::Ctrl('E') => {
                    if st.pos < st.line.len() {
                        st.pos = st.line.len();
                        st.move_cursor()?;
                    }
                }
                Key::Up | Key::Ctrl('P') => st.history_move(true)?,
                Key::Down | Key::Ctrl('N') => st.history_move(false)?,
                Key::Meta('<') => st.history_edge(true)?,
                Key::Meta('>') => st.history_edge(false)?,
                Key::Meta('p') | Key::Meta('P') => st.history_search(true)?,
                Key::Meta('n') | Key::Meta('N') => st.history_search(false)?,
                Key::Ctrl('K') => {
                    let (s, e) = (st.pos, st.line.len());
                    st.kill(s, e, &mut ring, true)?;
                    this_kill = true;
                }
                Key::Ctrl('U') => {
                    let (s, e) = (0, st.pos);
                    st.kill(s, e, &mut ring, false)?;
                    this_kill = true;
                }
                Key::Ctrl('W') => {
                    let s = st.prev_word_start(true);
                    let e = st.pos;
                    st.kill(s, e, &mut ring, false)?;
                    this_kill = true;
                }
                Key::MetaBackspace => {
                    let s = st.prev_word_start(false);
                    let e = st.pos;
                    st.kill(s, e, &mut ring, false)?;
                    this_kill = true;
                }
                Key::Meta('d') | Key::Meta('D') => {
                    let s = st.pos;
                    let e = st.next_word_end();
                    st.kill(s, e, &mut ring, true)?;
                    this_kill = true;
                }
                Key::Ctrl('Y') => {
                    if let Some(text) = ring.last().cloned() {
                        self.kill_index = ring.len() - 1;
                        let start = st.pos;
                        st.insert_str(&text)?;
                        this_yank = Some((start, st.pos));
                    } else {
                        st.beep()?;
                    }
                }
                Key::Meta('y') | Key::Meta('Y') => {
                    if let (Some((start, end)), false) = (st.last_action_yank, ring.is_empty()) {
                        if ring.len() > 1 {
                            self.kill_index = (self.kill_index + ring.len() - 1) % ring.len();
                        }
                        let text = ring[self.kill_index].clone();
                        st.snapshot();
                        st.line.drain(start..end);
                        st.pos = start;
                        for c in text.chars() {
                            st.line.insert(st.pos, c);
                            st.pos += 1;
                        }
                        st.changed()?;
                        this_yank = Some((start, st.pos));
                    } else {
                        st.beep()?;
                    }
                }
                Key::Ctrl('T') => {
                    if st.pos > 0 && st.line.len() >= 2 {
                        st.snapshot();
                        if st.pos == st.line.len() {
                            let n = st.line.len();
                            st.line.swap(n - 2, n - 1);
                        } else {
                            st.line.swap(st.pos - 1, st.pos);
                            st.pos += 1;
                        }
                        st.changed()?;
                    }
                }
                Key::Ctrl('L') => {
                    st.write("\x1b[H\x1b[J")?;
                    st.layout = Layout::default();
                    st.refresh(true)?;
                }
                Key::Tab | Key::BackTab => st.beep()?,
                Key::Meta('b') | Key::Meta('B') | Key::CtrlLeft => {
                    let p = st.prev_word_start(false);
                    if p != st.pos {
                        st.pos = p;
                        st.move_cursor()?;
                    }
                }
                Key::Meta('f') | Key::Meta('F') | Key::CtrlRight => {
                    let p = st.next_word_end();
                    if p != st.pos {
                        st.pos = p;
                        st.move_cursor()?;
                    }
                }
                Key::Meta('c') | Key::Meta('C') | Key::Meta('l') | Key::Meta('L') | Key::Meta('u')
                | Key::Meta('U') => {
                    let end = st.next_word_end();
                    if end > st.pos {
                        st.snapshot();
                        let mut i = st.pos;
                        while i < end && !is_word_char(st.line[i]) {
                            i += 1;
                        }
                        let mut first = true;
                        for j in i..end {
                            let c = st.line[j];
                            let nc: Vec<char> = match key {
                                Key::Meta('u') | Key::Meta('U') => c.to_uppercase().collect(),
                                Key::Meta('l') | Key::Meta('L') => c.to_lowercase().collect(),
                                _ => {
                                    if first {
                                        c.to_uppercase().collect()
                                    } else {
                                        c.to_lowercase().collect()
                                    }
                                }
                            };
                            first = false;
                            if let Some(&n) = nc.first() {
                                st.line[j] = n;
                            }
                        }
                        st.pos = end;
                        st.changed()?;
                    }
                }
                Key::Meta('t') | Key::Meta('T') => {
                    // transpose words around the cursor
                    let line = &st.line;
                    let n = line.len();
                    let mut e1 = st.pos;
                    while e1 > 0 && !is_word_char(line[e1 - 1]) {
                        e1 -= 1;
                    }
                    let mut s1 = e1;
                    while s1 > 0 && is_word_char(line[s1 - 1]) {
                        s1 -= 1;
                    }
                    let mut s2 = st.pos;
                    while s2 < n && !is_word_char(line[s2]) {
                        s2 += 1;
                    }
                    let mut e2 = s2;
                    while e2 < n && is_word_char(line[e2]) {
                        e2 += 1;
                    }
                    if s1 < e1 && s2 < e2 && e1 <= s2 {
                        st.snapshot();
                        let w1: Vec<char> = line[s1..e1].to_vec();
                        let sep: Vec<char> = line[e1..s2].to_vec();
                        let w2: Vec<char> = line[s2..e2].to_vec();
                        let mut new_line: Vec<char> = line[..s1].to_vec();
                        new_line.extend(w2);
                        new_line.extend(sep);
                        new_line.extend(w1);
                        new_line.extend(line[e2..].iter());
                        st.line = new_line;
                        st.pos = e2;
                        st.changed()?;
                    } else {
                        st.beep()?;
                    }
                }
                Key::Ctrl('_') => {
                    if let Some((l, p)) = st.undo.pop() {
                        st.line = l;
                        st.pos = p;
                        st.changed()?;
                    }
                }
                Key::Ctrl('X') => ctrl_x = true,
                Key::Ctrl('V') | Key::Ctrl('Q') => {
                    // quoted insert: next key inserted literally
                    if let Some(k) = reader.read_key()? {
                        let c = match k {
                            Key::Char(c) => Some(c),
                            Key::Ctrl(c) => Some(((c as u8) - 0x40) as char),
                            Key::Enter => Some('\n'),
                            Key::Tab => Some('\t'),
                            Key::Backspace => Some('\x7f'),
                            Key::Esc => Some('\x1b'),
                            _ => None,
                        };
                        if let Some(c) = c {
                            st.snapshot();
                            st.line.insert(st.pos, c);
                            st.pos += 1;
                            st.changed()?;
                        }
                    }
                }
                Key::Ctrl('Z') => {
                    // suspend the process and restore the editor afterwards
                    let raw = RawMode { original: unsafe { std::mem::zeroed() } };
                    drop(raw);
                    unsafe {
                        let mut t: libc::termios = std::mem::zeroed();
                        libc::tcgetattr(libc::STDIN_FILENO, &mut t);
                        libc::kill(libc::getpid(), libc::SIGTSTP);
                    }
                    st.layout = Layout::default();
                    st.refresh(true)?;
                }
                _ => {}
            }
            st.last_action_kill = this_kill;
            st.last_action_yank = this_yank;
        }
    }
}
EOF
echo ok"}

actions.command:
cat > /workspace/src/readline/mod.rs <<'EOF'
//! A small line editor with emacs key bindings, history, hints and syntax
//! highlighting, modelled after the behaviour of the usual readline-like
//! crates (prompt rendering, bracketed paste, synchronized updates, ...).

pub mod history;
pub mod term;

use std::io::{self, BufRead, Write};

use history::History;
use term::{Key, KeyReader, RawMode};

/// Behaviour hooks for highlighting.
pub trait Helper {
    /// Highlights the whole input line (ANSI escape sequences allowed).
    fn highlight(&self, line: &str) -> String;
    /// Highlights a hint displayed after the cursor.
    fn highlight_hint(&self, hint: &str) -> String;
}

#[derive(Debug)]
pub enum ReadlineError {
    Io(io::Error),
    Eof,
    Interrupted,
}

impl From<io::Error> for ReadlineError {
    fn from(e: io::Error) -> Self {
        ReadlineError::Io(e)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
struct Position {
    col: usize,
    row: usize,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
struct Layout {
    cursor: Position,
    end: Position,
}

pub struct Editor<H: Helper> {
    history: History,
    helper: Option<H>,
    kill_ring: Vec<String>,
    kill_index: usize,
}

const MAX_UNDO: usize = 200;

fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp < 0x20 || cp == 0x7f {
        return 0;
    }
    // combining marks
    if (0x0300..=0x036f).contains(&cp)
        || (0x1ab0..=0x1aff).contains(&cp)
        || (0x1dc0..=0x1dff).contains(&cp)
        || (0x20d0..=0x20ff).contains(&cp)
        || (0xfe20..=0xfe2f).contains(&cp)
        || cp == 0x200b
    {
        return 0;
    }
    // wide / fullwidth
    if (0x1100..=0x115f).contains(&cp)
        || (0x2e80..=0x303e).contains(&cp)
        || (0x3041..=0x33ff).contains(&cp)
        || (0x3400..=0x4dbf).contains(&cp)
        || (0x4e00..=0x9fff).contains(&cp)
        || (0xa000..=0xa4cf).contains(&cp)
        || (0xac00..=0xd7a3).contains(&cp)
        || (0xf900..=0xfaff).contains(&cp)
        || (0xfe30..=0xfe4f).contains(&cp)
        || (0xff00..=0xff60).contains(&cp)
        || (0xffe0..=0xffe6).contains(&cp)
        || (0x1f300..=0x1f64f).contains(&cp)
        || (0x1f900..=0x1f9ff).contains(&cp)
        || (0x20000..=0x3fffd).contains(&cp)
    {
        return 2;
    }
    1
}

fn is_word_char(c: char) -> bool {
    c.is_alphanumeric()
}

struct State<'a, H: Helper> {
    prompt: &'a str,
    prompt_size: Position,
    cols: usize,
    line: Vec<char>,
    pos: usize,
    layout: Layout,
    hint: Option<String>,
    history_index: usize,
    saved_line: Option<(Vec<char>, usize)>,
    undo: Vec<(Vec<char>, usize)>,
    colors: bool,
    helper: Option<&'a H>,
    history: &'a History,
    out: io::Stdout,
    last_action_kill: bool,
    last_action_yank: Option<(usize, usize)>,
}

impl<'a, H: Helper> State<'a, H> {
    fn calculate_position(&self, s: &[char], orig: Position) -> Position {
        let mut pos = orig;
        for &c in s {
            if c == '\n' {
                pos.row += 1;
                pos.col = 0;
                continue;
            }
            let cw = char_width(c);
            pos.col += cw;
            if pos.col > self.cols {
                pos.row += 1;
                pos.col = cw;
            }
        }
        if pos.col == self.cols {
            pos.col = 0;
            pos.row += 1;
        }
        pos
    }

    fn line_string(&self) -> String {
        self.line.iter().collect()
    }

    fn write(&mut self, s: &str) -> io::Result<()> {
        self.out.write_all(s.as_bytes())?;
        self.out.flush()
    }

    fn beep(&mut self) -> io::Result<()> {
        self.write("\x07")
    }

    /// Recomputes the history based hint for the current line.
    fn update_hint(&mut self) {
        self.hint = None;
        if self.line.is_empty() || self.pos < self.line.len() {
            return;
        }
        let start = if self.history_index == self.history.len() {
            self.history_index.saturating_sub(1)
        } else {
            self.history_index
        };
        let line = self.line_string();
        if let Some((_, entry)) = self.history.starts_with_rev(&line, start) {
            if *entry != line {
                self.hint = Some(entry[line.len()..].to_string());
            }
        }
    }

    fn refresh(&mut self, with_hint: bool) -> io::Result<()> {
        let hint = if with_hint { self.hint.clone() } else { None };
        let cursor = self.calculate_position(&self.line[..self.pos], self.prompt_size);
        let mut end = if self.pos == self.line.len() {
            cursor
        } else {
            self.calculate_position(&self.line[self.pos..], cursor)
        };
        if let Some(h) = &hint {
            let hc: Vec<char> = h.chars().collect();
            end = self.calculate_position(&hc, end);
        }

        let mut buf = String::new();
        buf.push_str(term::BEGIN_SYNC);
        let old = self.layout;
        let cursor_row_movement = old.end.row.saturating_sub(old.cursor.row);
        if cursor_row_movement > 0 {
            buf.push_str(&format!("\x1b[{}B", cursor_row_movement));
        }
        for _ in 0..old.end.row {
            buf.push_str("\r\x1b[K\x1b[A");
        }
        buf.push_str("\r\x1b[K");
        let line = self.line_string();
        buf.push_str(self.prompt);
        match (self.colors, self.helper) {
            (true, Some(h)) => buf.push_str(&h.highlight(&line)),
            _ => buf.push_str(&line),
        }
        if let Some(hint_text) = &hint {
            match (self.colors, self.helper) {
                (true, Some(h)) => buf.push_str(&h.highlight_hint(hint_text)),
                _ => buf.push_str(hint_text),
            }
        }
        if end.col == 0 && end.row > 0 && !hint.as_deref().map_or(false, |h| h.ends_with('\n')) {
            buf.push('\n');
        }
        let up = end.row.saturating_sub(cursor.row);
        if up > 0 {
            buf.push_str(&format!("\x1b[{}A", up));
        }
        if cursor.col > 0 {
            buf.push_str(&format!("\r\x1b[{}C", cursor.col));
        } else {
            buf.push('\r');
        }
        buf.push_str(term::END_SYNC);
        self.layout = Layout { cursor, end };
        self.write(&buf)
    }

    /// Called after the cursor moved without the text changing.
    fn move_cursor(&mut self) -> io::Result<()> {
        let cursor = self.calculate_position(&self.line[..self.pos], self.prompt_size);
        if self.layout.cursor == cursor {
            return Ok(());
        }
        if self.colors {
            self.update_hint();
            return self.refresh(true);
        }
        let old = self.layout.cursor;
        let mut buf = String::new();
        if cursor.row > old.row {
            let shift = cursor.row - old.row;
            if shift == 1 {
                buf.push_str("\x1b[B");
            } else {
                buf.push_str(&format!("\x1b[{}B", shift));
            }
        } else if cursor.row < old.row {
            let shift = old.row - cursor.row;
            if shift == 1 {
                buf.push_str("\x1b[A");
            } else {
                buf.push_str(&format!("\x1b[{}A", shift));
            }
        }
        if cursor.col > old.col {
            let shift = cursor.col - old.col;
            if shift == 1 {
                buf.push_str("\x1b[C");
            } else {
                buf.push_str(&format!("\x1b[{}C", shift));
            }
        } else if cursor.col < old.col {
            let shift = old.col - cursor.col;
            if shift == 1 {
                buf.push_str("\x1b[D");
            } else {
                buf.push_str(&format!("\x1b[{}D", shift));
            }
        }
        self.layout.cursor = cursor;
        self.write(&buf)
    }

    /// Called after the text changed.
    fn changed(&mut self) -> io::Result<()> {
        self.update_hint();
        self.refresh(true)
    }

    fn snapshot(&mut self) {
        if self.undo.len() >= MAX_UNDO {
            self.undo.remove(0);
        }
        self.undo.push((self.line.clone(), self.pos));
    }

    fn insert_char(&mut self, c: char) -> io::Result<()> {
        self.snapshot();
        self.line.insert(self.pos, c);
        self.pos += 1;
        let had_hint = self.hint.is_some();
        self.update_hint();
        if !self.colors && self.pos == self.line.len() && !had_hint && self.hint.is_none() && char_width(c) > 0 {
            // trivial case: append the character at the end of the line
            let w = char_width(c);
            let mut cursor = self.layout.cursor;
            cursor.col += w;
            if cursor.col >= self.cols {
                // wrapped: fall back to a full refresh
                return self.refresh(true);
            }
            self.layout.cursor = cursor;
            self.layout.end = cursor;
            let mut tmp = [0u8; 4];
            let s = c.encode_utf8(&mut tmp);
            return self.write(s);
        }
        self.refresh(true)
    }

    fn insert_str(&mut self, text: &str) -> io::Result<()> {
        if text.is_empty() {
            return Ok(());
        }
        self.snapshot();
        for c in text.chars() {
            self.line.insert(self.pos, c);
            self.pos += 1;
        }
        self.changed()
    }

    fn kill(&mut self, start: usize, end: usize, ring: &mut Vec<String>, append: bool) -> io::Result<()> {
        if start >= end {
            return Ok(());
        }
        self.snapshot();
        let text: String = self.line[start..end].iter().collect();
        self.line.drain(start..end);
        self.pos = start;
        if self.last_action_kill && !ring.is_empty() {
            let last = ring.len() - 1;
            if append {
                ring[last].push_str(&text);
            } else {
                ring[last] = format!("{}{}", text, ring[last]);
            }
        } else {
            ring.push(text);
        }
        self.changed()
    }

    fn prev_word_start(&self, big: bool) -> usize {
        let mut i = self.pos;
        if big {
            while i > 0 && self.line[i - 1].is_whitespace() {
                i -= 1;
            }
            while i > 0 && !self.line[i - 1].is_whitespace() {
                i -= 1;
            }
        } else {
            while i > 0 && !is_word_char(self.line[i - 1]) {
                i -= 1;
            }
            while i > 0 && is_word_char(self.line[i - 1]) {
                i -= 1;
            }
        }
        i
    }

    fn next_word_end(&self) -> usize {
        let n = self.line.len();
        let mut i = self.pos;
        while i < n && !is_word_char(self.line[i]) {
            i += 1;
        }
        while i < n && is_word_char(self.line[i]) {
            i += 1;
        }
        i
    }

    fn history_move(&mut self, prev: bool) -> io::Result<()> {
        if self.history.is_empty() {
            return Ok(());
        }
        if self.history_index == self.history.len() {
            if prev {
                self.saved_line = Some((self.line.clone(), self.pos));
            } else {
                return Ok(());
            }
        } else if self.history_index == 0 && prev {
            return Ok(());
        }
        if prev {
            self.history_index -= 1;
        } else {
            self.history_index += 1;
        }
        self.snapshot();
        if self.history_index < self.history.len() {
            let entry = self.history.get(self.history_index).unwrap();
            self.line = entry.chars().collect();
            self.pos = self.line.len();
        } else if let Some((l, p)) = self.saved_line.take() {
            self.line = l;
            self.pos = p;
        }
        self.changed()
    }

    fn history_edge(&mut self, first: bool) -> io::Result<()> {
        if self.history.is_empty() {
            return Ok(());
        }
        if first {
            if self.history_index == self.history.len() {
                self.saved_line = Some((self.line.clone(), self.pos));
            } else if self.history_index == 0 {
                return Ok(());
            }
            self.history_index = 0;
            self.snapshot();
            let entry = self.history.get(0).unwrap();
            self.line = entry.chars().collect();
            self.pos = self.line.len();
        } else {
            if self.history_index == self.history.len() {
                return Ok(());
            }
            self.history_index = self.history.len();
            self.snapshot();
            if let Some((l, p)) = self.saved_line.take() {
                self.line = l;
                self.pos = p;
            } else {
                self.line.clear();
                self.pos = 0;
            }
        }
        self.changed()
    }

    fn history_search(&mut self, prev: bool) -> io::Result<()> {
        if self.history.is_empty() {
            return Ok(());
        }
        let prefix: String = self.line[..self.pos].iter().collect();
        let found = if prev {
            if self.history_index == 0 {
                None
            } else {
                let start = self.history_index.min(self.history.len()) - 1;
                self.history.starts_with_rev(&prefix, start).map(|(i, e)| (i, e.clone()))
            }
        } else {
            if self.history_index + 1 >= self.history.len() {
                None
            } else {
                self.history.starts_with_fwd(&prefix, self.history_index + 1).map(|(i, e)| (i, e.clone()))
            }
        };
        match found {
            Some((idx, entry)) => {
                if self.history_index == self.history.len() {
                    self.saved_line = Some((self.line.clone(), self.pos));
                }
                self.history_index = idx;
                self.snapshot();
                self.line = entry.chars().collect();
                self.pos = self.pos.min(self.line.len());
                self.changed()
            }
            None => self.beep(),
        }
    }
}

impl<H: Helper> Editor<H> {
    pub fn new(history: History) -> Self {
        Editor {
            history,
            helper: None,
            kill_ring: Vec::new(),
            kill_index: 0,
        }
    }

    pub fn set_helper(&mut self, helper: H) {
        self.helper = Some(helper);
    }

    pub fn history_mut(&mut self) -> &mut History {
        &mut self.history
    }

    pub fn add_history_entry(&mut self, line: &str) -> bool {
        self.history.add(line)
    }

    fn read_direct() -> Result<String, ReadlineError> {
        let mut input = String::new();
        let n = io::stdin().lock().read_line(&mut input)?;
        if n == 0 {
            return Err(ReadlineError::Eof);
        }
        if input.ends_with('\n') {
            input.pop();
            if input.ends_with('\r') {
                input.pop();
            }
        }
        Ok(input)
    }

    pub fn readline(&mut self, prompt: &str) -> Result<String, ReadlineError> {
        if term::is_unsupported_term() {
            let mut out = io::stdout();
            out.write_all(prompt.as_bytes())?;
            out.flush()?;
            return Self::read_direct();
        }
        if !term::is_tty(libc::STDIN_FILENO) {
            return Self::read_direct();
        }
        let raw = RawMode::enable()?;
        let result = self.edit(prompt);
        raw.disable();
        let mut out = io::stdout();
        let _ = out.write_all(b"\n");
        let _ = out.flush();
        result
    }

    fn edit(&mut self, prompt: &str) -> Result<String, ReadlineError> {
        let colors = term::is_tty(libc::STDOUT_FILENO);
        let cols = term::columns();
        let prompt_chars: Vec<char> = prompt.chars().collect();
        let mut st = State {
            prompt,
            prompt_size: Position::default(),
            cols,
            line: Vec::new(),
            pos: 0,
            layout: Layout::default(),
            hint: None,
            history_index: self.history.len(),
            saved_line: None,
            undo: Vec::new(),
            colors,
            helper: self.helper.as_ref(),
            history: &self.history,
            out: io::stdout(),
            last_action_kill: false,
            last_action_yank: None,
        };
        st.prompt_size = st.calculate_position(&prompt_chars, Position::default());
        st.refresh(true)?;

        let mut reader = KeyReader::new();
        let mut ring = std::mem::take(&mut self.kill_ring);
        let mut ctrl_x = false;
        loop {
            let key = match reader.read_key()? {
                Some(k) => k,
                None => {
                    self.kill_ring = ring;
                    return Err(ReadlineError::Eof);
                }
            };
            let mut this_kill = false;
            let mut this_yank: Option<(usize, usize)> = None;
            if ctrl_x {
                ctrl_x = false;
                match key {
                    Key::Ctrl('U') => {
                        if let Some((l, p)) = st.undo.pop() {
                            st.line = l;
                            st.pos = p;
                            st.changed()?;
                        }
                    }
                    _ => {}
                }
                continue;
            }
            match key {
                Key::Char(c) => st.insert_char(c)?,
                Key::Paste(text) => {
                    let text = text.replace("\r\n", "\n").replace('\r', "\n");
                    st.insert_str(&text)?;
                }
                Key::Enter | Key::Ctrl('J') | Key::Ctrl('M') => {
                    if st.pos != st.line.len() {
                        st.pos = st.line.len();
                        st.move_cursor()?;
                    }
                    if st.hint.is_some() || st.colors {
                        st.refresh(false)?;
                    }
                    self.kill_ring = ring;
                    return Ok(st.line_string());
                }
                Key::Ctrl('C') => {
                    self.kill_ring = ring;
                    return Err(ReadlineError::Interrupted);
                }
                Key::Ctrl('D') => {
                    if st.line.is_empty() {
                        if st.hint.is_some() || st.colors {
                            st.refresh(false)?;
                        }
                        self.kill_ring = ring;
                        return Err(ReadlineError::Eof);
                    } else if st.pos < st.line.len() {
                        st.snapshot();
                        st.line.remove(st.pos);
                        st.changed()?;
                    }
                }
                Key::Delete => {
                    if st.pos < st.line.len() {
                        st.snapshot();
                        st.line.remove(st.pos);
                        st.changed()?;
                    }
                }
                Key::Backspace | Key::Ctrl('H') => {
                    if st.pos > 0 {
                        st.snapshot();
                        st.pos -= 1;
                        st.line.remove(st.pos);
                        st.changed()?;
                    }
                }
                Key::Left | Key::Ctrl('B') => {
                    if st.pos > 0 {
                        st.pos -= 1;
                        st.move_cursor()?;
                    }
                }
                Key::Right | Key::Ctrl('F') => {
                    if st.pos < st.line.len() {
                        st.pos += 1;
                        st.move_cursor()?;
                    } else if let Some(h) = st.hint.clone() {
                        st.insert_str(&h)?;
                    }
                }
                Key::Home | Key::Ctrl('A') => {
                    if st.pos > 0 {
                        st.pos = 0;
                        st.move_cursor()?;
                    }
                }
                Key::End | Key::Ctrl('E') => {
                    if st.pos < st.line.len() {
                        st.pos = st.line.len();
                        st.move_cursor()?;
                    }
                }
                Key::Up | Key::Ctrl('P') => st.history_move(true)?,
                Key::Down | Key::Ctrl('N') => st.history_move(false)?,
                Key::Meta('<') => st.history_edge(true)?,
                Key::Meta('>') => st.history_edge(false)?,
                Key::Meta('p') | Key::Meta('P') => st.history_search(true)?,
                Key::Meta('n') | Key::Meta('N') => st.history_search(false)?,
                Key::Ctrl('K') => {
                    let (s, e) = (st.pos, st.line.len());
                    st.kill(s, e, &mut ring, true)?;
                    this_kill = true;
                }
                Key::Ctrl('U') => {
                    let (s, e) = (0, st.pos);
                    st.kill(s, e, &mut ring, false)?;
                    this_kill = true;
                }
                Key::Ctrl('W') => {
                    let s = st.prev_word_start(true);
                    let e = st.pos;
                    st.kill(s, e, &mut ring, false)?;
                    this_kill = true;
                }
                Key::MetaBackspace => {
                    let s = st.prev_word_start(false);
                    let e = st.pos;
                    st.kill(s, e, &mut ring, false)?;
                    this_kill = true;
                }
                Key::Meta('d') | Key::Meta('D') => {
                    let s = st.pos;
                    let e = st.next_word_end();
                    st.kill(s, e, &mut ring, true)?;
                    this_kill = true;
                }
                Key::Ctrl('Y') => {
                    if let Some(text) = ring.last().cloned() {
                        self.kill_index = ring.len() - 1;
                        let start = st.pos;
                        st.insert_str(&text)?;
                        this_yank = Some((start, st.pos));
                    } else {
                        st.beep()?;
                    }
                }
                Key::Meta('y') | Key::Meta('Y') => {
                    if let (Some((start, end)), false) = (st.last_action_yank, ring.is_empty()) {
                        if ring.len() > 1 {
                            self.kill_index = (self.kill_index + ring.len() - 1) % ring.len();
                        }
                        let text = ring[self.kill_index].clone();
                        st.snapshot();
                        st.line.drain(start..end);
                        st.pos = start;
                        for c in text.chars() {
                            st.line.insert(st.pos, c);
                            st.pos += 1;
                        }
                        st.changed()?;
                        this_yank = Some((start, st.pos));
                    } else {
                        st.beep()?;
                    }
                }
                Key::Ctrl('T') => {
                    if st.pos > 0 && st.line.len() >= 2 {
                        st.snapshot();
                        if st.pos == st.line.len() {
                            let n = st.line.len();
                            st.line.swap(n - 2, n - 1);
                        } else {
                            st.line.swap(st.pos - 1, st.pos);
                            st.pos += 1;
                        }
                        st.changed()?;
                    }
                }
                Key::Ctrl('L') => {
                    st.write("\x1b[H\x1b[J")?;
                    st.layout = Layout::default();
                    st.refresh(true)?;
                }
                Key::Tab | Key::BackTab => st.beep()?,
                Key::Meta('b') | Key::Meta('B') | Key::CtrlLeft => {
                    let p = st.prev_word_start(false);
                    if p != st.pos {
                        st.pos = p;
                        st.move_cursor()?;
                    }
                }
                Key::Meta('f') | Key::Meta('F') | Key::CtrlRight => {
                    let p = st.next_word_end();
                    if p != st.pos {
                        st.pos = p;
                        st.move_cursor()?;
                    }
                }
                Key::Meta('c') | Key::Meta('C') | Key::Meta('l') | Key::Meta('L') | Key::Meta('u')
                | Key::Meta('U') => {
                    let end = st.next_word_end();
                    if end > st.pos {
                        st.snapshot();
                        let mut i = st.pos;
                        while i < end && !is_word_char(st.line[i]) {
                            i += 1;
                        }
                        let mut first = true;
                        for j in i..end {
                            let c = st.line[j];
                            let nc: Vec<char> = match key {
                                Key::Meta('u') | Key::Meta('U') => c.to_uppercase().collect(),
                                Key::Meta('l') | Key::Meta('L') => c.to_lowercase().collect(),
                                _ => {
                                    if first {
                                        c.to_uppercase().collect()
                                    } else {
                                        c.to_lowercase().collect()
                                    }
                                }
                            };
                            first = false;
                            if let Some(&n) = nc.first() {
                                st.line[j] = n;
                            }
                        }
                        st.pos = end;
                        st.changed()?;
                    }
                }
                Key::Meta('t') | Key::Meta('T') => {
                    // transpose words around the cursor
                    let line = &st.line;
                    let n = line.len();
                    let mut e1 = st.pos;
                    while e1 > 0 && !is_word_char(line[e1 - 1]) {
                        e1 -= 1;
                    }
                    let mut s1 = e1;
                    while s1 > 0 && is_word_char(line[s1 - 1]) {
                        s1 -= 1;
                    }
                    let mut s2 = st.pos;
                    while s2 < n && !is_word_char(line[s2]) {
                        s2 += 1;
                    }
                    let mut e2 = s2;
                    while e2 < n && is_word_char(line[e2]) {
                        e2 += 1;
                    }
                    if s1 < e1 && s2 < e2 && e1 <= s2 {
                        st.snapshot();
                        let w1: Vec<char> = line[s1..e1].to_vec();
                        let sep: Vec<char> = line[e1..s2].to_vec();
                        let w2: Vec<char> = line[s2..e2].to_vec();
                        let mut new_line: Vec<char> = line[..s1].to_vec();
                        new_line.extend(w2);
                        new_line.extend(sep);
                        new_line.extend(w1);
                        new_line.extend(line[e2..].iter());
                        st.line = new_line;
                        st.pos = e2;
                        st.changed()?;
                    } else {
                        st.beep()?;
                    }
                }
                Key::Ctrl('_') => {
                    if let Some((l, p)) = st.undo.pop() {
                        st.line = l;
                        st.pos = p;
                        st.changed()?;
                    }
                }
                Key::Ctrl('X') => ctrl_x = true,
                Key::Ctrl('V') | Key::Ctrl('Q') => {
                    // quoted insert: next key inserted literally
                    if let Some(k) = reader.read_key()? {
                        let c = match k {
                            Key::Char(c) => Some(c),
                            Key::Ctrl(c) => Some(((c as u8) - 0x40) as char),
                            Key::Enter => Some('\n'),
                            Key::Tab => Some('\t'),
                            Key::Backspace => Some('\x7f'),
                            Key::Esc => Some('\x1b'),
                            _ => None,
                        };
                        if let Some(c) = c {
                            st.snapshot();
                            st.line.insert(st.pos, c);
                            st.pos += 1;
                            st.changed()?;
                        }
                    }
                }
                Key::Ctrl('Z') => {
                    // suspend the process and restore the editor afterwards
                    let raw = RawMode { original: unsafe { std::mem::zeroed() } };
                    drop(raw);
                    unsafe {
                        let mut t: libc::termios = std::mem::zeroed();
                        libc::tcgetattr(libc::STDIN_FILENO, &mut t);
                        libc::kill(libc::getpid(), libc::SIGTSTP);
                    }
                    st.layout = Layout::default();
                    st.refresh(true)?;
                }
                _ => {}
            }
            st.last_action_kill = this_kill;
            st.last_action_yank = this_yank;
        }
    }
}
