use crate::readline::Helper;

const RED: &str = "\x1b[31m";
const BLUE: &str = "\x1b[34m";
const YELLOW: &str = "\x1b[33m";
const MAGENTA: &str = "\x1b[35m";
const GRAY: &str = "\x1b[90m";
const RESET: &str = "\x1b[0m";

/// Characters that are treated as operators when colouring.
const HL_OPERATORS: &[char] = &['+', '-', '*', '/', '^', '%', '!', ',', '.'];

fn colored(text: &str, color: &str) -> String {
    format!("{}{}{}", color, text, RESET)
}

pub struct EvaHelper;

impl EvaHelper {
    pub fn new() -> Self {
        EvaHelper
    }
}

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Plain,
    Operator,
    Function(usize),
    Constant(usize),
}

impl Helper for EvaHelper {
    fn highlight(&self, line: &str) -> String {
        if evaluate(line, None, AngleUnit::Degree).is_err() {
            return colored(line, RED);
        }
        let chars: Vec<char> = line.chars().collect();
        let n = chars.len();
        let mut kinds = vec![Kind::Plain; n];

        // function calls: `name(`
        let functions: HashMap<&str, usize> = FUNCTIONS.iter().copied().collect();
        let mut id = 0;
        for name in functions.keys() {
            let pat: Vec<char> = format!("{}(", name).chars().collect();
            let mut i = 0;
            while i + pat.len() <= n {
                if chars[i..i + pat.len()] == pat[..] && kinds[i..i + pat.len() - 1].iter().all(|k| *k == Kind::Plain) {
                    id += 1;
                    for k in kinds.iter_mut().take(i + pat.len() - 1).skip(i) {
                        *k = Kind::Function(id);
                    }
                    i += pat.len();
                } else {
                    i += 1;
                }
            }
        }

        // constants followed by an operator, whitespace or the end of line
        for (name, _) in CONSTANTS.iter() {
            let pat: Vec<char> = name.chars().collect();
            let mut i = 0;
            while i + pat.len() <= n {
                let end = i + pat.len();
                let follows_ok = end == n || HL_OPERATORS.contains(&chars[end]) || chars[end].is_whitespace();
                let precedes_ok = i == 0 || !chars[i - 1].is_alphabetic();
                if chars[i..end] == pat[..] && follows_ok && precedes_ok && kinds[i..end].iter().all(|k| *k == Kind::Plain) {
                    id += 1;
                    for k in kinds.iter_mut().take(end).skip(i) {
                        *k = Kind::Constant(id);
                    }
                    i = end;
                } else {
                    i += 1;
                }
            }
        }

        // operators
        for (i, c) in chars.iter().enumerate() {
            if HL_OPERATORS.contains(c) && kinds[i] == Kind::Plain {
                kinds[i] = Kind::Operator;
            }
        }

        let mut out = String::new();
        let mut i = 0;
        while i < n {
            match kinds[i] {
                Kind::Plain => {
                    out.push(chars[i]);
                    i += 1;
                }
                Kind::Operator => {
                    out.push_str(&colored(&chars[i].to_string(), MAGENTA));
                    i += 1;
                }
                k @ (Kind::Function(_) | Kind::Constant(_)) => {
                    let mut j = i;
                    while j < n && kinds[j] == k {
                        j += 1;
                    }
                    let text: String = chars[i..j].iter().collect();
                    let color = if matches!(k, Kind::Function(_)) { BLUE } else { YELLOW };
                    out.push_str(&colored(&text, color));
                    i = j;
                }
            }
        }
        out
    }

    fn highlight_hint(&self, hint: &str) -> String {
        colored(hint, GRAY)
    }
}

#[allow(dead_code)]
pub fn operator_chars() -> &'static [char] {
    OPERATOR_CHARS
