mod error;
mod format;
mod highlight;
mod lexer;
mod parser;
mod readline;

use std::fs;
use std::io::Write;
use std::path::PathBuf;

use clap::{Arg, ArgAction, Command};

use highlight::EvaHelper;
use parser::AngleUnit;
use readline::history::History;
use readline::{Editor, ReadlineError};

struct Config {
    fix: usize,
    base: u32,
    unit: AngleUnit,
    input: Option<String>,
}

fn parse_args() -> Config {
    let cmd = Command::new("eva")
        .version("0.3.1")
        .about("Calculator REPL similar to bc(1)")
        .arg(
            Arg::new("fix")
                .short('f')
                .long("fix")
                .value_name("FIX")
                .help("Number of decimal places in output (1 - 64)")
                .default_value("10")
                .value_parser(clap::value_parser!(u8).range(1..=64))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("base")
                .short('b')
                .long("base")
                .value_name("RADIX")
                .help("Radix of calculation output (1 - 36)")
                .default_value("10")
                .value_parser(clap::value_parser!(u8).range(1..=36))
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("angle_unit")
                .short('a')
                .long("angle_unit")
                .value_name("angle_unit")
                .help("Angle unit")
                .default_value("degree")
                .value_parser(["degree", "radian", "gradian"])
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new("INPUT")
                .help("Optional expression string to run eva in command mode")
                .action(ArgAction::Set),
        );
    let matches = cmd.get_matches();
    let fix = *matches.get_one::<u8>("fix").unwrap() as usize;
    let base = *matches.get_one::<u8>("base").unwrap() as u32;
    let unit = match matches.get_one::<String>("angle_unit").unwrap().as_str() {
        "radian" => AngleUnit::Radian,
        "gradian" => AngleUnit::Gradian,
        _ => AngleUnit::Degree,
    };
    let input = matches.get_one::<String>("INPUT").cloned();
    Config { fix, base, unit, input }
}

/// Home directory: `$HOME` or the passwd entry of the current user.
fn home_dir() -> Option<PathBuf> {
    if let Some(home) = std::env::var_os("HOME") {
        if !home.is_empty() {
            return Some(PathBuf::from(home));
        }
    }
    unsafe {
        let pw = libc::getpwuid(libc::getuid());
        if pw.is_null() || (*pw).pw_dir.is_null() {
            return None;
        }
        let dir = std::ffi::CStr::from_ptr((*pw).pw_dir);
        let s = dir.to_string_lossy().into_owned();
        if s.is_empty() {
            None
        } else {
            Some(PathBuf::from(s))
        }
    }
}

fn xdg_dir(var: &str, fallback: &[&str]) -> Option<PathBuf> {
    if let Some(v) = std::env::var_os(var) {
        let p = PathBuf::from(v);
        if p.is_absolute() {
            return Some(p);
        }
    }
    let mut home = home_dir()?;
    for part in fallback {
        home.push(part);
    }
    Some(home)
}

fn cache_dir() -> Option<PathBuf> {
    xdg_dir("XDG_CACHE_HOME", &[".cache"])
}

fn data_dir() -> Option<PathBuf> {
    xdg_dir("XDG_DATA_HOME", &[".local", "share"])
}

fn command_mode(config: &Config, expr: &str) {
    match parser::evaluate(expr, Some(0.0), config.unit) {
        Ok(v) => println!("{}", format::pprint(v, config.fix, config.base)),
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    }
}

fn repl(config: &Config) {
    // previous answer cache
    let mut cache = cache_dir().unwrap_or_else(|| PathBuf::from("."));
    cache.push("eva");
    let _ = fs::create_dir_all(&cache);
    let previous_ans_path = cache.join("previous_ans.txt");
    match fs::File::create(&previous_ans_path).and_then(|mut f| f.write_all(b"0")) {
        Ok(()) => {}
        Err(e) => {
            println!("Could not write to previous_ans_path");
            println!("{:?}", e);
            std::process::exit(1);
        }
    }

    // history
    let mut data = data_dir().unwrap_or_else(|| PathBuf::from("."));
    data.push("eva");
    let _ = fs::create_dir_all(&data);
    let history_path = data.join("history.txt");

    let mut rl: Editor<EvaHelper> = Editor::new(History::new(1000));
    rl.set_helper(EvaHelper::new());
    if rl.history_mut().load(&history_path).is_err() {
        println!("No previous history.");
    }

    let mut prev_ans: Option<f64> = None;
    loop {
        match rl.readline("> ") {
            Ok(line) => {
                rl.add_history_entry(&line);
                match parser::evaluate(&line, prev_ans, config.unit) {
                    Ok(v) => {
                        println!("{}", format::pprint(v, config.fix, config.base));
                        let rounded = format::round_to_fix(v, config.fix);
                        prev_ans = Some(rounded);
                        if let Err(e) = fs::File::create(&previous_ans_path)
                            .and_then(|mut f| writeln!(f, "{}", rounded))
                        {
                            println!("Error while writing previous answer to file: {}", e);
                        }
                    }
                    Err(e) => println!("{}", e),
                }
            }
            Err(ReadlineError::Interrupted) => {
                println!("CTRL-C");
                break;
            }
            Err(ReadlineError::Eof) => break,
            Err(e) => {
                println!("Error: {:?}", e);
                break;
            }
        }
    }
    rl.history_mut().save(&history_path).map_err(ReadlineError::Io).unwrap();
}

fn main() {
    let config = parse_args();
    match &config.input {
        Some(expr) if !expr.is_empty() => command_mode(&config, expr),
        _ => repl(&config),
    }
}
