main = '''//! eva — a simple calculator REPL similar to bc(1).
//!
//! The program has two modes of operation:
//!
//! * **command mode**: when an expression is given on the command line it is
//!   evaluated, the result is printed and the program exits;
//! * **REPL mode**: without an expression an interactive prompt is shown.
//!   Lines are read with a small line editor that offers history, hints and
//!   syntax highlighting, every result is printed and remembered so that it
//!   can be referred to with the underscore (`_`) symbol.
//!
//! State that survives between sessions:
//!
//! * the command history, stored in `$XDG_DATA_HOME/eva/history.txt`
//!   (falling back to `~/.local/share/eva/history.txt`);
//! * the last answer, stored in `$XDG_CACHE_HOME/eva/previous_ans.txt`
//!   (falling back to `~/.cache/eva/previous_ans.txt`).
//!
//! When one of those directories cannot be created the file is placed
//! directly in the home directory instead.

mod cli;
mod error;
mod format;
mod highlight;
mod lexer;
mod parser;
mod paths;
mod readline;

use std::fs;
use std::io::Write;
use std::path::Path;

use cli::{parse_args, Config};
use highlight::EvaHelper;
use paths::{cache_dir, data_dir, resolve_path};
use readline::history::History;
use readline::{Editor, ReadlineError};

/// Evaluates a single expression given on the command line.
///
/// Results go to stdout, errors to stderr with a non-zero exit status.  In
/// this mode no state is read or written and `_` evaluates to zero.
fn command_mode(config: &Config, expr: &str) {
    match parser::evaluate(expr, Some(0.0), config.unit) {
        Ok(v) => println!("{}", format::pprint(v, config.fix, config.base)),
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    }
}

/// Creates (or truncates) the previous answer file and resets it to `0`.
fn reset_previous_answer(path: &Path) -> std::io::Result<()> {
    let mut file = fs::File::create(path)?;
    file.write_all(b"0")
}

/// Records the latest answer.  The file is rewritten in place without being
/// truncated first, exactly like the original tool does.
fn store_previous_answer(path: &Path, value: f64) -> std::io::Result<()> {
    let mut file = fs::OpenOptions::new().write(true).create(true).open(path)?;
    writeln!(file, "{}", value)
}

/// Evaluates one REPL line and prints the outcome.  Returns the (rounded)
/// value when the evaluation succeeded.
fn eval_line(config: &Config, line: &str, prev_ans: Option<f64>) -> Option<f64> {
    match parser::evaluate(line, prev_ans, config.unit) {
        Ok(v) => {
            println!("{}", format::pprint(v, config.fix, config.base));
            Some(format::round_to_fix(v, config.fix))
        }
        Err(e) => {
            println!("{}", e);
            None
        }
    }
}

/// Runs the interactive read-eval-print loop.
fn repl(config: &Config) {
    // The previous answer lives in the cache directory and starts at zero
    // for every session (the stored value is only informational).
    let previous_ans_path = resolve_path(cache_dir(), "previous_ans.txt");
    if let Err(e) = reset_previous_answer(&previous_ans_path) {
        println!("Could not write to previous_ans_path");
        println!("{:?}", e);
        std::process::exit(1);
    }

    // The history lives in the data directory.
    let history_filepath = resolve_path(data_dir(), "history.txt");

    let mut line_editor: Editor<EvaHelper> = Editor::new(History::new(1000));
    line_editor.set_helper(EvaHelper::new());
    if line_editor.load_history(&history_filepath).is_err() {
        println!("No previous history.");
    }

    let mut prev_ans: Option<f64> = None;
    loop {
        match line_editor.readline("> ") {
            Ok(line) => {
                line_editor.add_history_entry(&line);
                if let Some(value) = eval_line(config, &line, prev_ans) {
                    prev_ans = Some(value);
                    if let Err(e) = store_previous_answer(&previous_ans_path, value) {
                        println!("Error while writing previous answer to file: {}", e);
                    }
                }
            }
            Err(ReadlineError::Interrupted) => {
                println!("CTRL-C");
                break;
            }
            Err(ReadlineError::Eof) => break,
            Err(e) => {
                println!("Error: {:?}", e);
                break;
            }
        }
    }

    // Persist the history; failing to do so is fatal.
    line_editor.save_history(&history_filepath).unwrap();
}

fn main() {
    let config = parse_args();
    match &config.input {
        Some(expr) if !expr.is_empty() => command_mode(&config, expr),
        _ => repl(&config),
    }
}
