/// Finds the start of the word ending at `pos` (escaped break characters do
/// not split words).
fn extract_word(line: &[char], pos: usize) -> usize {
    let line = &line[..pos];
    if line.is_empty() {
        return 0;
    }
    let mut start: Option<usize> = None;
    let mut i = line.len();
    while i > 0 {
        i -= 1;
        let c = line[i];
        if start.is_some() {
            if c == ESCAPE_CHAR {
