                if BREAK_CHARS.contains(&n) {
                    out.push(n);
                    iter.next();
                    continue;
                }
            }
        }
        out.push(c);
    }
    out
}

fn escape(path: &str) -> String {
    let mut out = String::with_capacity(path.len());
    for c in path.chars() {
        if BREAK_CHARS.contains(&c) {
            out.push(ESCAPE_CHAR);
        }
        out.push(c);
    }
    out
